/* Card set: Wild Mammals (generated from the approved roster.csv by the Wild Mammals build).
   (wild-mammals.js exceeds the comfortable push size, so the remaining cards live in
   wild-mammals-additions.js, which must stay directly after 'wild-mammals.js' in sets/manifest.js.) */
CardSets.register({"id":"wild-mammals","name":"Wild Mammals","code":"MAMM","description":"420 wild species and nothing else: big cats, bears and primates, hoofed herds, rodents, marsupials and bats. No domestics, no marine mammals, no people.","theme":{"primary":"#a67c2e","secondary":"#e0b45c","artBackground":"#171208","artFit":"cover"},"pack":{"name":"Wild Mammals Pack","emblem":"🐅","skin":"wild-mammals"},"cards":[{"name":"Bengal Tiger","rarity":"chase","id":"bengal-tiger","subtitle":"Carnivore","details":"India's Bengal tiger is the most numerous tiger subspecies, a striped ambush hunter of deer and wild boar in forests and mangrove swamps.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bengal_tiger_in_Sanjay_Dubri_Tiger_Reserve_December_2024_by_Tisha_Mukherjee_11.jpg?width=1024"},{"name":"African Lion","rarity":"chase","id":"african-lion","subtitle":"Carnivore","details":"The African lion is the only truly social big cat, living in prides across sub-Saharan savannas where females hunt cooperatively.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/020_The_lion_king_Snyggve_in_the_Serengeti_National_Park_Photo_by_Giles_Laurent.jpg?width=1024"},{"name":"African Elephant","rarity":"chase","id":"african-elephant","subtitle":"Oddball","details":"The largest land animal on Earth, this African savanna elephant uses its trunk — part nose, part hand — to grasp food, drink, and greet its herd.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/African_Elephant_%28Loxodonta_africana%29_male_%2817289351322%29.jpg?width=1024"},{"name":"Grizzly Bear","rarity":"chase","id":"grizzly-bear","subtitle":"Carnivore","details":"The grizzly bear of western North America digs for roots, bulbs and ground squirrels with long front claws and a muscular shoulder hump.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/GrizzlyBearJeanBeaufort.jpg?width=1024"},{"name":"Polar Bear","rarity":"chase","id":"polar-bear","subtitle":"Carnivore","details":"The polar bear hunts seals from Arctic sea ice, its hollow, translucent fur appearing white over black, heat-absorbing skin.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Polar_Bear_-_Alaska_%28cropped%29.jpg?width=1024"},{"name":"Gray Wolf","rarity":"chase","id":"gray-wolf","subtitle":"Carnivore","details":"The gray wolf, largest wild member of the dog family, lives in packs across northern forests, tundra and mountains on several continents.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eurasian_wolf_2.jpg?width=1024"},{"name":"Giant Panda","rarity":"chase","id":"giant-panda","subtitle":"Carnivore","details":"China's giant panda eats bamboo almost exclusively, using an enlarged wrist bone as a thumb to grip the tough stems.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Grosser_Panda.JPG?width=1024"},{"name":"Red Panda","rarity":"chase","id":"red-panda","subtitle":"Carnivore","details":"The red panda of Himalayan forests is a bamboo-eating climber with rusty fur, a striped tail and a false thumb like the giant panda's.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Red_Panda%2C_Gentle_Tree-Dweller_of_the_Himalayas.jpg?width=1024"},{"name":"Mountain Gorilla","rarity":"chase","id":"mountain-gorilla","subtitle":"Primate","details":"In Rwanda, Uganda and Congo's Virunga highlands, families led by a silverback feed on leaves, stems and shoots in misty mountain forest.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Susa_group%2C_mountain_gorilla.jpg?width=1024"},{"name":"Platypus","rarity":"chase","id":"platypus","subtitle":"Oddball","details":"Australia's egg-laying platypus hunts underwater with eyes shut, sensing prey through electroreception in its broad, duck-like bill.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Duck-billed_platypus_%28Ornithorhynchus_anatinus%29_Scottsdale.jpg?width=1024"},{"name":"Moose","rarity":"legendary","id":"moose","subtitle":"Hoofed Mammal","details":"The largest deer on Earth, a bull moose can stand over two metres at the shoulder, with broad palmate antlers it sheds and regrows every year.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alaska_moose.jpg?width=1024"},{"name":"Jaguar","rarity":"legendary","id":"jaguar","subtitle":"Carnivore","details":"The jaguar, the Americas' largest cat, is a powerful swimmer that hunts caimans and capybaras along rainforest rivers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Standing_jaguar.jpg?width=1024"},{"name":"Leopard","rarity":"legendary","id":"leopard","subtitle":"Carnivore","details":"The leopard ranges across Africa and Asia, hoisting kills into trees to keep them from lions and hyenas, and swims readily.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/African_leopard_male_%28cropped%29.jpg?width=1024"},{"name":"Cheetah","rarity":"legendary","id":"cheetah","subtitle":"Carnivore","details":"The cheetah is the fastest land animal, sprinting after gazelles in bursts powered by a flexible spine and non-retractable claws.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Male_cheetah_facing_left_in_South_Africa.jpg?width=1024"},{"name":"Snow Leopard","rarity":"legendary","id":"snow-leopard","subtitle":"Carnivore","details":"The snow leopard prowls Central Asia's high mountains, its thick smoky coat and long tail aiding balance and warmth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Irbis4.JPG?width=1024"},{"name":"African Wild Dog","rarity":"legendary","id":"african-wild-dog","subtitle":"Carnivore","details":"African wild dogs hunt in packs with a success rate among the highest of any predator, chasing antelope across open savanna.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/African_Wild_Dog_at_Working_with_Wildlife.jpg?width=1024"},{"name":"Spotted Hyena","rarity":"legendary","id":"spotted-hyena","subtitle":"Carnivore","details":"The spotted hyena lives in large clans led by females and can crush bone with some of the strongest jaws of any mammal.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Spotted_hyena_%28Crocuta_crocuta%29.jpg?width=1024"},{"name":"Wolverine","rarity":"legendary","id":"wolverine","subtitle":"Carnivore","details":"The wolverine, a stocky mustelid of northern forests and tundra, roams huge territories and can drive bears from a carcass.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/J%C3%A4rv1.jpg?width=1024"},{"name":"Giant Otter","rarity":"legendary","id":"giant-otter","subtitle":"Carnivore","details":"The giant otter, up to 1.8 metres long, hunts fish in family groups along Amazonian rivers and oxbow lakes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Giant_otters_%28Pteronura_brasiliensis%29.jpg?width=1024"},{"name":"Fossa","rarity":"legendary","id":"fossa","subtitle":"Carnivore","details":"Madagascar's largest predator, the fossa is a cat-like euplerid that climbs trees to hunt lemurs through the forest canopy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cryptoprocta_Ferox.JPG?width=1024"},{"name":"Maned Wolf","rarity":"legendary","id":"maned-wolf","subtitle":"Carnivore","details":"The maned wolf stalks South American grasslands on stilt-like legs, eating small prey and the tomato-like lobeira fruit.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lobo_Guar%C3%A1_andando.jpg?width=1024"},{"name":"Chimpanzee","rarity":"legendary","id":"chimpanzee","subtitle":"Primate","details":"Widespread across equatorial Africa's forests and savannas, chimpanzees live in large communities, use tools and greet each other with gestures.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/015_Chimpanzee_at_Kibale_forest_National_Park_Photo_by_Giles_Laurent.jpg?width=800"},{"name":"Bornean Orangutan","rarity":"legendary","id":"bornean-orangutan","subtitle":"Primate","details":"Borneo's great red ape spends most of its life alone in the treetops, building a fresh leafy nest to sleep in every night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tanjung_Puting30477.jpg?width=1024"},{"name":"Western Lowland Gorilla","rarity":"legendary","id":"western-lowland-gorilla","subtitle":"Primate","details":"The most numerous gorilla lives in the rainforests of Congo, Gabon and Cameroon, travelling on the ground in family groups led by a silverback.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/WesternLowlandGorilla03.jpg?width=1024"},{"name":"Mandrill","rarity":"legendary","id":"mandrill","subtitle":"Primate","details":"Rainforest mandrills of Cameroon and Gabon sport the brightest faces of any mammal: ridged blue cheeks and a scarlet nose on adult males.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mandrill_Albert_September_2015_Zoo_Berlin_%282%29.jpg?width=800"},{"name":"Ring-tailed Lemur","rarity":"legendary","id":"ring-tailed-lemur","subtitle":"Primate","details":"Madagascar's famous lemur lives in troops in dry southern forests, sunbathing upright at dawn and walking with its striped tail held high.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ring-tailed%20lemur%20%28Lemur%20catta%29%20in%20tree.jpg?width=1024"},{"name":"Proboscis Monkey","rarity":"legendary","id":"proboscis-monkey","subtitle":"Primate","details":"Borneo's mangrove swimmer is unmistakable: males carry a huge dangling nose and paddle expertly between riverside trees.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Proboscis_Monkey_in_Borneo.jpg?width=1024"},{"name":"Giraffe","rarity":"legendary","id":"giraffe","subtitle":"Hoofed Mammal","details":"The tallest land animal, a giraffe's heart weighs about 11 kilograms to pump blood up its long neck, and no two giraffes share the same spot pattern.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Giraffe_Mikumi_National_Park.jpg?width=1024"},{"name":"Okapi","rarity":"legendary","id":"okapi","subtitle":"Hoofed Mammal","details":"A shy forest relative of the giraffe found only in Congo rainforest, the okapi has zebra-striped legs and a tongue long enough to lick its own eyes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Saint-Aignan_%28Loir-et-Cher%29._Okapi.jpg?width=1024"},{"name":"White Rhinoceros","rarity":"legendary","id":"white-rhinoceros","subtitle":"Hoofed Mammal","details":"Despite its name, this huge grazer is grey; 'white' likely comes from a word for 'wide', describing the broad square lip it uses to crop grass.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/109_Male_White_rhinoceros_walking_in_the_Kalahari_Desert_of_Namibia_Photo_by_Giles_Laurent.jpg?width=1024"},{"name":"Hippopotamus","rarity":"legendary","id":"hippopotamus","subtitle":"Hoofed Mammal","details":"A hippo spends most of the day in rivers to keep its skin cool, secreting a pinkish natural sunscreen, then grazes on land through the night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Portrait_Hippopotamus_in_the_water.jpg?width=1024"},{"name":"Capybara","rarity":"legendary","id":"capybara","subtitle":"Rodent","details":"The largest living rodent, this semi-aquatic South American grazer can top 60 kilograms and swims with ease between riverbanks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Capybaracropped.jpg?width=1024"},{"name":"American Beaver","rarity":"legendary","id":"american-beaver","subtitle":"Rodent","details":"North America's largest rodent fells trees with ever-growing orange incisors and builds dams and lodges that reshape whole streams.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/American_Beaver.jpg?width=1024"},{"name":"Koala","rarity":"legendary","id":"koala","subtitle":"Marsupial","details":"The koala sleeps up to twenty hours a day in eucalyptus branches, digesting tough gum leaves that few other animals can manage to eat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Koala_climbing_tree.jpg?width=1024"},{"name":"Red Kangaroo","rarity":"legendary","id":"red-kangaroo","subtitle":"Marsupial","details":"The largest of all marsupials, the red kangaroo of Australia's dry interior can bound at highway speeds and leap nine metres in a single hop.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Red_kangaroo_-_melbourne_zoo.jpg?width=1024"},{"name":"Tasmanian Devil","rarity":"legendary","id":"tasmanian-devil","subtitle":"Marsupial","details":"This stocky Tasmanian marsupial has one of the strongest bites for its size of any mammal, and its eerie night screams earned it the name devil.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sarcophilus%20harrisii%20taranna%20edit.jpg?width=1024"},{"name":"Giant Anteater","rarity":"legendary","id":"giant-anteater","subtitle":"Oddball","details":"South America's giant anteater laps up ants with a tongue that can stretch over half a metre and flick in and out 150 times a minute.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/037%20Giant%20anteater%20in%20Encontro%20das%20%C3%81guas%20State%20Park%20Photo%20by%20Giles%20Laurent.jpg?width=1024"},{"name":"Hammer-headed Bat","rarity":"legendary","id":"hammer-headed-bat","subtitle":"Bat","details":"African fruit bat whose males sport huge hammer-shaped heads and voice boxes, honking loudly at riverside gatherings to attract mates at night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hypsignathus%20monstrosus.png?width=500"},{"name":"Grey-headed Flying Fox","rarity":"legendary","id":"grey-headed-flying-fox","subtitle":"Bat","details":"A large Australian fruit bat that roosts in noisy treetop camps by day and flies out at dusk to feed on nectar, pollen and native fruit.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Grey_headed_flying_fox_-_Mating_behaviour_-_AndrewMercer_-_DSC11277_-_crop.jpg?width=1024"},{"name":"Indian Flying Fox","rarity":"legendary","id":"indian-flying-fox","subtitle":"Bat","details":"One of the world's largest bats, this South Asian fruit bat hangs in huge tree colonies and pollinates flowers as it feeds through the night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/047_Indian_flying_fox_in_Keoladeo_National_Park_Photo_by_Giles_Laurent.jpg?width=1024"},{"name":"Cougar","rarity":"epic","id":"cougar","subtitle":"Carnivore","details":"The cougar, also called puma or mountain lion, ranges from Canada to Patagonia, the widest spread of any American land mammal.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mountain_Lion_in_Glacier_National_Park.jpg?width=1024"},{"name":"Clouded Leopard","rarity":"epic","id":"clouded-leopard","subtitle":"Carnivore","details":"The clouded leopard of Asian forests has the longest canine teeth relative to its skull of any living cat, and climbs superbly.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Neofelis_nebulosa%2C_Clouded_leopard.jpg?width=1024"},{"name":"Eurasian Lynx","rarity":"epic","id":"eurasian-lynx","subtitle":"Carnivore","details":"The Eurasian lynx, Europe and Asia's largest lynx, hunts roe deer and hares in forests from Scandinavia to Siberia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lynx_Nationalpark_Bayerischer_Wald_01.jpg?width=1024"},{"name":"Dhole","rarity":"epic","id":"dhole","subtitle":"Carnivore","details":"The dhole is a russet Asian wild dog that hunts deer in packs, communicating with whistles through dense jungle.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dhole_%28Asiatic_wild_dog%29_cropped.jpg?width=1024"},{"name":"Honey Badger","rarity":"epic","id":"honey-badger","subtitle":"Carnivore","details":"The honey badger, or ratel, is a fearless African and Asian mustelid famous for raiding beehives and shrugging off snakes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Honey_Badger.jpg?width=1024"},{"name":"Binturong","rarity":"epic","id":"binturong","subtitle":"Carnivore","details":"The binturong, or bearcat, is a shaggy Southeast Asian viverrid with a prehensile tail and a scent that smells of popcorn.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Binturong_in_Overloon.jpg?width=1024"},{"name":"Striped Hyena","rarity":"epic","id":"striped-hyena","subtitle":"Carnivore","details":"The striped hyena scavenges across North Africa and Asia, raising its long striped mane to look larger when threatened.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Striped_hyena_in_Bhigwan_August_2025_by_Tisha_Mukherjee_07_%28cropped%29.jpg?width=800"},{"name":"Serval","rarity":"epic","id":"serval","subtitle":"Carnivore","details":"The serval is a long-legged African cat that leaps high to snatch birds mid-air and pounces on rodents in tall grass.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Servalcropped.png?width=500"},{"name":"Caracal","rarity":"epic","id":"caracal","subtitle":"Carnivore","details":"The caracal is a sleek desert cat of Africa and Asia, famed for its black ear tufts and acrobatic bird-catching leaps.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Caracal_on_the_road%2C_early_morning_in_Kgalagadi_%2836173878220%29_%28cropped%29.jpg?width=1024"},{"name":"Ocelot","rarity":"epic","id":"ocelot","subtitle":"Carnivore","details":"The ocelot is a beautifully blotched nocturnal cat of American forests, about twice the size of a house cat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/016_Ocelot_in_Encontro_das_%C3%81guas_State_Park_Photo_by_Giles_Laurent.jpg?width=1024"},{"name":"American Black Bear","rarity":"epic","id":"american-black-bear","subtitle":"Carnivore","details":"The American black bear is North America's smallest, most common bear, an expert climber that comes in colors from black to blond.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vancouver_Island_black_bear_%28Ursus_americanus_vancouveri%29_Tofino_4.jpg?width=1024"},{"name":"Asian Black Bear","rarity":"epic","id":"asian-black-bear","subtitle":"Carnivore","details":"The Asian black bear, marked by a pale chest crescent, climbs trees across Asia's forests to feed on nuts, fruit and insects.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ursus_thibetanus_3_%28Wroclaw_zoo%29.JPG?width=1024"},{"name":"Spectacled Bear","rarity":"epic","id":"spectacled-bear","subtitle":"Carnivore","details":"South America's only bear, the spectacled bear climbs Andean cloud-forest trees and builds platforms to reach fruit.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tremarctos_ornatus_in_Jardim_Zool%C3%B3gico_de_Curitiba.jpg?width=1024"},{"name":"Bonobo","rarity":"epic","id":"bonobo","subtitle":"Primate","details":"South of the Congo River, bonobos live in peaceful, female-led groups and settle most disagreements with grooming and embraces.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ulrik%2C%20jeune%20de%201%20ans%20avec%20sa%20m%C3%A8re%20Uma.%20LuiKotale%2C%20RDC.jpg?width=1024"},{"name":"Sumatran Orangutan","rarity":"epic","id":"sumatran-orangutan","subtitle":"Primate","details":"Sumatra's slender, pale-bearded orangutan rarely leaves the canopy, moving slowly hand over hand through fruiting treetops.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sumatra-Orang-Utan_im_Pongoland.jpg?width=1024"},{"name":"Japanese Macaque","rarity":"epic","id":"japanese-macaque","subtitle":"Primate","details":"Japan's snow monkeys endure snowy winters in the northern hills, famously warming themselves in natural hot springs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Japanese_Snow_Monkey_%28Macaque%29_Mother_Grooms_Her_Young.jpg?width=1024"},{"name":"Hamadryas Baboon","rarity":"epic","id":"hamadryas-baboon","subtitle":"Primate","details":"Sacred to ancient Egyptians, hamadryas baboons of Arabia and the Horn of Africa sleep on cliffs in troops of several hundred.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hamadryas%20baboon%20%28Papio%20hamadryas%29%20mother%20and%20baby.jpg?width=1024"},{"name":"Gelada","rarity":"epic","id":"gelada","subtitle":"Primate","details":"High on Ethiopia's grass plateaus, geladas graze like antelope, flashing a bare hourglass patch of chest skin to signal mood.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gelada_%28Theropithecus_gelada_gelada%29_male_2.jpg?width=1024"},{"name":"Golden Snub-nosed Monkey","rarity":"epic","id":"golden-snub-nosed-monkey","subtitle":"Primate","details":"In China's cold mountain forests, golden snub-nosed monkeys huddle together for warmth beneath thick orange-gold coats.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Golden_Snub-nosed_Monkeys%2C_Qinling_Mountains_-_China.jpg?width=1024"},{"name":"Red-shanked Douc Langur","rarity":"epic","id":"red-shanked-douc-langur","subtitle":"Primate","details":"Vietnam and Laos' rainbow langur wears maroon shins, a white tail and a golden face as it leaps through rainforest canopy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Red-shanked_douc_langur_%28Pygathrix_nemaeus%29_female_and_juvenile_Son_Tra.jpg?width=1024"},{"name":"Aye-aye","rarity":"epic","id":"aye-aye","subtitle":"Primate","details":"Madagascar's nocturnal aye-aye taps dead wood with its long, thin middle finger, listening for grubs to fish out like a woodpecker.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wild_aye_aye.jpg?width=1024"},{"name":"African Buffalo","rarity":"epic","id":"african-buffalo","subtitle":"Hoofed Mammal","details":"One of Africa's most formidable grazers, the buffalo's fused horn bases form a solid shield called a boss, and herds defend calves together.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/African_buffalo_%28Syncerus_caffer_caffer%29_male_with_cattle_egret.jpg?width=1024"},{"name":"American Bison","rarity":"epic","id":"american-bison","subtitle":"Hoofed Mammal","details":"North America's largest land animal once roamed in immense herds; a bison's massive shoulder hump is muscle that powers it through deep snow.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/American_bison_k5680-1.jpg?width=1024"},{"name":"Plains Zebra","rarity":"epic","id":"plains-zebra","subtitle":"Hoofed Mammal","details":"Each plains zebra's stripe pattern is unique, and foals learn their mother's pattern; stripes may help confuse biting flies and predators alike.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Equus_quagga_burchellii_-_Etosha%2C_2014.jpg?width=1024"},{"name":"Indian Rhinoceros","rarity":"epic","id":"indian-rhinoceros","subtitle":"Hoofed Mammal","details":"The one-horned rhino of Nepal and Assam wears folds of thick skin like armour plating and is a strong swimmer, grazing in tall river grasslands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Great-Indian-one-horned-rhinoceros-at-Kaziranga-national-park-in-Assam-India.jpg?width=1024"},{"name":"Malayan Tapir","rarity":"epic","id":"malayan-tapir","subtitle":"Hoofed Mammal","details":"The largest tapir, this black-and-white 'saddleback' of Southeast Asian forests uses its short flexible trunk to grab leaves and sniff out food.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Schabrackentapir_Tapirus_indicus_Tiergarten-Nuernberg-1.jpg?width=1024"},{"name":"Greater Kudu","rarity":"epic","id":"greater-kudu","subtitle":"Hoofed Mammal","details":"A bull greater kudu's spiral horns can grow over a metre long, yet this tall, striped antelope slips silently through thornbush without a sound.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Male_greater_kudu.jpg?width=1024"},{"name":"Gemsbok","rarity":"epic","id":"gemsbok","subtitle":"Hoofed Mammal","details":"A striking desert oryx of the Kalahari, the gemsbok's rapier-straight horns and bold face markings help it thrive where water is scarce.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gemsbok_%28Oryx_gazella%29_male.jpg?width=1024"},{"name":"Muskox","rarity":"epic","id":"muskox","subtitle":"Hoofed Mammal","details":"An Arctic survivor since the Ice Age, the muskox grows a double coat; its soft underwool, qiviut, is among the warmest natural fibres known.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Muskox_%28Ovibos_moschatus%29_male_Dovrefjell_4.jpg?width=1024"},{"name":"Markhor","rarity":"epic","id":"markhor","subtitle":"Hoofed Mammal","details":"Pakistan's national animal, the markhor is a wild goat named for its spectacular corkscrew horns, climbing sheer cliffs in Central Asian mountains.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Markhor_Schraubenziege_Capra_falconeri_Zoo_Augsburg-02.jpg?width=1024"},{"name":"Pronghorn","rarity":"epic","id":"pronghorn","subtitle":"Hoofed Mammal","details":"North America's fastest land mammal over distance, the pronghorn is the last survivor of its family and sheds the outer sheath of its horns yearly.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Antilocapra_americana.jpg?width=1024"},{"name":"Eurasian Beaver","rarity":"epic","id":"eurasian-beaver","subtitle":"Rodent","details":"This dam-building rodent of Europe and Asia stores winter food underwater and enters its lodge through a submerged doorway.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Beaver_pho34.jpg?width=1024"},{"name":"Crested Porcupine","rarity":"epic","id":"crested-porcupine","subtitle":"Rodent","details":"Africa's largest rodent defends itself with banded black-and-white quills up to half a metre long, rattled as a warning first.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hystrix_cristata_qtl1.jpg?width=1024"},{"name":"North American Porcupine","rarity":"epic","id":"north-american-porcupine","subtitle":"Rodent","details":"This slow, tree-climbing rodent carries some 30,000 barbed quills that detach on contact and lodge in a predator's skin.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/North_American_porcupine_%28Erethizon_dorsatum_nigrescens%29_Yoho.jpg?width=1024"},{"name":"Patagonian Mara","rarity":"epic","id":"patagonian-mara","subtitle":"Rodent","details":"A long-legged, hare-like rodent of Argentine grasslands, the mara grazes in monogamous pairs and raises pups in communal burrows.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dolichotis_patagonum_99386074.jpg?width=1024"},{"name":"Snowshoe Hare","rarity":"epic","id":"snowshoe-hare","subtitle":"Small Mammal","details":"Named for its oversized hind feet, this North American hare turns white in winter and feeds on twigs and bark when snow is deep.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lepus_americanus_5459_cropped.jpg?width=1024"},{"name":"European Hedgehog","rarity":"epic","id":"european-hedgehog","subtitle":"Small Mammal","details":"Covered in some 5,000 spines, this nocturnal insect-eater rolls into a tight ball when threatened and hibernates through winters.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Erinaceus_europaeus_LC0119.jpg?width=1024"},{"name":"Asian Elephant","rarity":"epic","id":"asian-elephant","subtitle":"Oddball","details":"Smaller than its African cousin and with only one 'finger' on its trunk tip, the Asian elephant has lived alongside people for thousands of years.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Elephas_maximus_%28Bandipur%29.jpg?width=1024"},{"name":"Aardvark","rarity":"epic","id":"aardvark","subtitle":"Oddball","details":"Africa's aardvark digs burrows with astonishing speed, then spends the night sniffing out termite mounds with its long, pig-like snout.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Orycteropus_afer_175359469.jpg?width=1024"},{"name":"Nine-banded Armadillo","rarity":"epic","id":"nine-banded-armadillo","subtitle":"Oddball","details":"When startled, this armoured American mammal can jump straight up over a metre into the air; it almost always gives birth to identical quadruplets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dasypus_novemcinctus_en_Zool%C3%B3gico_de_Paraguan%C3%A1.jpg?width=1024"},{"name":"Ground Pangolin","rarity":"epic","id":"ground-pangolin","subtitle":"Oddball","details":"Africa's ground pangolin walks on its hind legs like a tiny dinosaur, covered in overlapping scales of keratin — the stuff of fingernails.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ground%20Pangolin%20at%20Madikwe%20Game%20Reserve.jpg?width=1024"},{"name":"Short-beaked Echidna","rarity":"epic","id":"short-beaked-echidna","subtitle":"Oddball","details":"One of only five egg-laying mammals, Australia's short-beaked echidna laps up ants and termites with a long, sticky tongue and has no teeth at all.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wild_shortbeak_echidna.jpg?width=1024"},{"name":"Straw-coloured Fruit Bat","rarity":"epic","id":"straw-coloured-fruit-bat","subtitle":"Bat","details":"A wide-ranging African fruit bat named for its yellowish fur; vast colonies migrate with the seasons, spreading tree seeds across the continent.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eidolon_helvum_fg01.JPG?width=1024"},{"name":"Egyptian Fruit Bat","rarity":"epic","id":"egyptian-fruit-bat","subtitle":"Bat","details":"A cave-roosting fruit bat of Africa and Asia, unusual among fruit bats for using tongue-click echolocation to navigate in total darkness.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skraidantis_egipto_%C5%A1uo_%28cropped%29.jpg?width=1024"},{"name":"Spectacled Flying Fox","rarity":"epic","id":"spectacled-flying-fox","subtitle":"Bat","details":"A rainforest fruit bat of Australia and New Guinea, named for the pale eye rings that give it a bespectacled look as it roosts in treetop camps.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pteropus_conspicillatus_family.jpg?width=1024"},{"name":"Common Vampire Bat","rarity":"epic","id":"common-vampire-bat","subtitle":"Bat","details":"A small Latin American bat that laps blood from sleeping livestock, walking on its thumbs and sensing heat to find where blood flows close.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Desmo-Flug-01.jpg?width=1024"},{"name":"Bobcat","rarity":"rare","id":"bobcat","subtitle":"Carnivore","details":"The bobcat is a North American lynx named for its short, bobbed tail, hunting rabbits from deserts to swamps.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bobcat_at_Columbus_Zoo_Boo.jpg?width=800"},{"name":"Canada Lynx","rarity":"rare","id":"canada-lynx","subtitle":"Carnivore","details":"The Canada lynx stalks snowshoe hares in boreal forests, walking atop deep snow on oversized, fur-covered paws.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Canada_lynx_by_Michael_Zahra_%28cropped%29.jpg?width=1024"},{"name":"Iberian Lynx","rarity":"rare","id":"iberian-lynx","subtitle":"Carnivore","details":"The Iberian lynx, a rabbit specialist of Spanish scrubland, sports a spotted coat, ear tufts and a distinctive beard.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lince_ib%C3%A9rico_%28Lynx_pardinus%29%2C_Almuradiel%2C_Ciudad_Real%2C_Espa%C3%B1a%2C_2021-12-19%2C_DD_07.jpg?width=1024"},{"name":"Fishing Cat","rarity":"rare","id":"fishing-cat","subtitle":"Carnivore","details":"The fishing cat of South and Southeast Asian wetlands dives into water to scoop fish, its toes partly webbed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Prionailurus_viverrinus_01.jpg?width=1024"},{"name":"Sun Bear","rarity":"rare","id":"sun-bear","subtitle":"Carnivore","details":"The sun bear, smallest of the bears, climbs Southeast Asian trees and tears open nests with a tongue up to 25 cm long.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sun-bear.jpg?width=1024"},{"name":"Sloth Bear","rarity":"rare","id":"sloth-bear","subtitle":"Carnivore","details":"The sloth bear of India vacuums up termites and ants with protruding lips, having lost its front teeth for suction feeding.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sloth_Bear_Washington_DC.JPG?width=1024"},{"name":"Brown Hyena","rarity":"rare","id":"brown-hyena","subtitle":"Carnivore","details":"The brown hyena scavenges South Africa's deserts and coasts, foraging alone at night for carcasses and fallen fruit.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Brown_Hyena_%28Hyaena_brunnea%29_leaving_waterhole_..._%2850915531592%29%2C_crop.jpg?width=1024"},{"name":"Ethiopian Wolf","rarity":"rare","id":"ethiopian-wolf","subtitle":"Carnivore","details":"The Ethiopian wolf, Africa's rarest canid, hunts giant mole-rats and other rodents alone in high Afroalpine meadows and moorlands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ethiopian_wolf_%28Canis_simensis_citernii%29.jpg?width=1024"},{"name":"Coyote","rarity":"rare","id":"coyote","subtitle":"Carnivore","details":"The coyote is an adaptable North American canid whose howls and yips fill deserts, prairies and even suburbs at night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2009-Coyote-Yosemite.jpg?width=1024"},{"name":"Golden Jackal","rarity":"rare","id":"golden-jackal","subtitle":"Carnivore","details":"The golden jackal ranges from southeastern Europe to Southeast Asia, pairing for life and scavenging in family groups.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/033_Golden_jackal_in_Keoladeo_National_Park_Photo_by_Giles_Laurent.jpg?width=1024"},{"name":"Black-backed Jackal","rarity":"rare","id":"black-backed-jackal","subtitle":"Carnivore","details":"The black-backed jackal, marked by a dark saddle, is a familiar scavenger and hunter of southern and eastern African savannas.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/135_Black-backed_jackal_hunting_for_food_at_Cape_cross_Photo_by_Giles_Laurent.jpg?width=1024"},{"name":"Aardwolf","rarity":"rare","id":"aardwolf","subtitle":"Carnivore","details":"The aardwolf is a termite-eating hyena relative of southern and eastern Africa, licking up thousands of termites a night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aardwolf%2C_Buffalo_Springs_National_Park%2C_Kenya_1_%28cropped%29.jpg?width=1024"},{"name":"Tayra","rarity":"rare","id":"tayra","subtitle":"Carnivore","details":"The tayra is a long-tailed, tree-climbing weasel of Central and South American forests that hunts rodents and enjoys fruit.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tayra_-_Male%2C_Brazil_%28cropped%29.jpg?width=1024"},{"name":"Fisher","rarity":"rare","id":"fisher","subtitle":"Carnivore","details":"The fisher is a powerful North American mustelid, one of the few predators able to hunt porcupines regularly.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fishers_%2814584727897%29.jpg?width=1024"},{"name":"North American River Otter","rarity":"rare","id":"north-american-river-otter","subtitle":"Carnivore","details":"The North American river otter slides down muddy banks and swims with webbed feet through rivers, lakes and coastal marshes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Northern_River_Otter_on_Seedskadee_NWR_%2822802102984%29.jpg?width=1024"},{"name":"Eurasian Otter","rarity":"rare","id":"eurasian-otter","subtitle":"Carnivore","details":"The Eurasian otter hunts fish in rivers and coasts from Ireland to Japan, marking its territory with scented spraint.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fischotter%2C_Lutra_Lutra.JPG?width=1024"},{"name":"Meerkat","rarity":"rare","id":"meerkat","subtitle":"Carnivore","details":"Meerkats live in Kalahari mobs where sentries stand upright on lookout while others dig for insects and scorpions.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Meerkat_%28Suricata_suricatta%29_Tswalu.jpg?width=1024"},{"name":"African Civet","rarity":"rare","id":"african-civet","subtitle":"Carnivore","details":"The African civet is a large, spotted, nocturnal viverrid that marks trees with musky secretions across sub-Saharan Africa.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Civettictis_civetta_11.jpg?width=1024"},{"name":"Siamang","rarity":"rare","id":"siamang","subtitle":"Primate","details":"The largest gibbon, Sumatra and Malaya's siamang inflates a throat sac to boom duets that carry for miles through the forest.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Siamang%20Symphalangus%20syndactylus%20%287930225230%29.jpg?width=1024"},{"name":"Lar Gibbon","rarity":"rare","id":"lar-gibbon","subtitle":"Primate","details":"Also called the white-handed gibbon, this agile ape of Southeast Asia swings hand over hand beneath the canopy at startling speed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hylobates_lar_pair_of_white_and_black_01.jpg?width=1024"},{"name":"Olive Baboon","rarity":"rare","id":"olive-baboon","subtitle":"Primate","details":"Africa's most widespread baboon ranges from savanna to forest edge in troops that forage on the ground by day for almost anything edible.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Olive_baboon_Ngorongoro.jpg?width=1024"},{"name":"Celebes Crested Macaque","rarity":"rare","id":"celebes-crested-macaque","subtitle":"Primate","details":"Sulawesi's jet-black macaque wears a punk crest of spiky hair and a heart-shaped pink rump, living in noisy rainforest troops.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kuifmakaak_%288721744168%29.jpg?width=1024"},{"name":"Barbary Macaque","rarity":"rare","id":"barbary-macaque","subtitle":"Primate","details":"The only macaque outside Asia, Barbary apes of Morocco and Algeria's cedar forests grow thick coats for cold mountain winters.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Macaca_sylvanus.Mother_and_baby.jpg?width=1024"},{"name":"Mantled Guereza","rarity":"rare","id":"mantled-guereza","subtitle":"Primate","details":"East Africa's black-and-white colobus sails between treetops trailing a long mantle of white fur and a tasselled tail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Guereza%20Abisinio%20%28Colobus%20guereza%29%2C%20parque%20nacional%20de%20la%20Selva%20Impenetrable%20de%20Bwindi%2C%20Uganda%2C%202024-02-02%2C%20DD%2002.jpg?width=1024"},{"name":"Mantled Howler Monkey","rarity":"rare","id":"mantled-howler-monkey","subtitle":"Primate","details":"Central America's loudest voice: a male howler's dawn chorus, deepened by an enlarged throat bone, carries three miles through forest.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panamanian_Male_Adult_Howler_Monkey.jpg?width=1024"},{"name":"Black-handed Spider Monkey","rarity":"rare","id":"black-handed-spider-monkey","subtitle":"Primate","details":"From Mexico to Colombia, spider monkeys swing by lanky limbs and a grasping tail that works like a fifth hand in the canopy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Geoffroy%27s_spider_monkey_%28Ateles_geoffroyi_yucatanensis%29_male_Peten.jpg?width=1024"},{"name":"Emperor Tamarin","rarity":"rare","id":"emperor-tamarin","subtitle":"Primate","details":"Named for its magnificent white moustache, said to echo Emperor Wilhelm II's, this tiny tamarin scampers through Amazon treetops.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tamarin_portrait.JPG?width=1024"},{"name":"Golden Lion Tamarin","rarity":"rare","id":"golden-lion-tamarin","subtitle":"Primate","details":"Rio de Janeiro's Atlantic forest glows with this little monkey's fiery mane as it probes bromeliads for frogs and insects.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Golden%20lion%20tamarin%20portrait3.jpg?width=1024"},{"name":"Cotton-top Tamarin","rarity":"rare","id":"cotton-top-tamarin","subtitle":"Primate","details":"Colombia's punk-crested tamarin raises twins on its back, the whole family taking turns carrying the babies through the branches.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/1_cotton_top_tamarin.jpg?width=1024"},{"name":"Indri","rarity":"rare","id":"indri","subtitle":"Primate","details":"Madagascar's largest living lemur sings eerie, whale-like duets from the treetops and leaps upright between the trunks of eastern rainforest.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Indri_%28Indri_indri%29.jpg?width=1024"},{"name":"European Bison","rarity":"rare","id":"european-bison","subtitle":"Hoofed Mammal","details":"The wisent is Europe's heaviest land animal, a forest-dwelling cousin of the American bison that browses leaves and bark in ancient woodlands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/European_bison_%28Bison_bonasus%29_male_Bia%C5%82owieza.jpg?width=1024"},{"name":"Black Rhinoceros","rarity":"rare","id":"black-rhinoceros","subtitle":"Hoofed Mammal","details":"A browser rather than a grazer, the black rhino uses its pointed, hooked upper lip to pluck leaves and twigs from bushes in African savannas.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Black_Rhino_at_Working_with_Wildlife.jpg?width=1024"},{"name":"Grevy's Zebra","rarity":"rare","id":"grevys-zebra","subtitle":"Hoofed Mammal","details":"The largest wild horse, Grevy's zebra has narrow stripes, a white belly and big rounded ears, and foals are born with brown, fuzzy striping.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Grevy%27s_Zebra_Stallion.jpg?width=1024"},{"name":"Mountain Zebra","rarity":"rare","id":"mountain-zebra","subtitle":"Hoofed Mammal","details":"This sure-footed zebra of rocky southern African highlands has a gridiron stripe pattern on its rump and a distinctive flap of skin on its throat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Equus_zebra_hartmannae_-_Etosha_2015.jpg?width=1024"},{"name":"Brazilian Tapir","rarity":"rare","id":"brazilian-tapir","subtitle":"Hoofed Mammal","details":"South America's largest native land mammal, the lowland tapir swims well and uses its mobile snout to browse fruit and leaves along forest trails.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/South_American_tapir_%28Tapirus_terrestris%29.JPG?width=1024"},{"name":"Baird's Tapir","rarity":"rare","id":"bairds-tapir","subtitle":"Hoofed Mammal","details":"Central America's largest land mammal, Baird's tapir is an expert swimmer that follows worn paths through rainforest to rivers and mud wallows.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Baird%27s_tapir_mother_with_baby_%2892151%29.jpg?width=1024"},{"name":"Pygmy Hippopotamus","rarity":"rare","id":"pygmy-hippopotamus","subtitle":"Hoofed Mammal","details":"Far smaller and more solitary than its famous cousin, the pygmy hippo is a secretive forest dweller of West Africa that forages alone at night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hexaprotodon_liberiensis_in_Edinburgh_Zoo.JPG?width=1024"},{"name":"Common Eland","rarity":"rare","id":"common-eland","subtitle":"Hoofed Mammal","details":"Africa's largest antelope can weigh as much as a small car, yet elands are remarkable jumpers, clearing two metres from a standing start.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Taurotragus_oryx_-_young_bull_-_Etosha_2015.jpg?width=1024"},{"name":"Arabian Oryx","rarity":"rare","id":"arabian-oryx","subtitle":"Hoofed Mammal","details":"A white antelope built for the Arabian desert, the oryx can go weeks without drinking, getting moisture from the plants it grazes at dawn.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Arabian_oryx_%28oryx_leucoryx%29.jpg?width=1024"},{"name":"Sable Antelope","rarity":"rare","id":"sable-antelope","subtitle":"Hoofed Mammal","details":"A bull sable's glossy black coat and long scimitar horns make it one of Africa's most striking antelope, bold enough to face down lions.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sable_antelope_%28Hippotragus_niger%29_adult_male.jpg?width=1024"},{"name":"Bighorn Sheep","rarity":"rare","id":"bighorn-sheep","subtitle":"Hoofed Mammal","details":"Rams settle contests by charging and clashing horns at speed in the mountains of western North America, cushioned by double-layered skulls.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/New_Mexico_Bighorn_Sheep.JPG?width=1024"},{"name":"Alpine Ibex","rarity":"rare","id":"alpine-ibex","subtitle":"Hoofed Mammal","details":"A wild goat of the high Alps, the ibex climbs near-vertical dam walls to lick salt from the stones, hooves splayed for grip on tiny ledges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/003_Wild_Alpine_Ibex_Sunset_Creux_du_Van_Mont_Racine_Photo_by_Giles_Laurent.jpg?width=1024"},{"name":"Wild Yak","rarity":"rare","id":"wild-yak","subtitle":"Hoofed Mammal","details":"A huge wild ox of the Tibetan Plateau, the wild yak endures bitter cold and thin air at altitudes above 4,000 metres, feeding on alpine grasses.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wild_Yak_Stuffed.jpg?width=1024"},{"name":"Gaur","rarity":"rare","id":"gaur","subtitle":"Hoofed Mammal","details":"The largest wild cattle species, a bull gaur can top two metres at the shoulder; this muscular forest ox ranges across South and Southeast Asia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Indian_Gaur_from_anaimalai_hills_JEG5290.jpg?width=1024"},{"name":"Groundhog","rarity":"rare","id":"groundhog","subtitle":"Rodent","details":"Also called the woodchuck, this burrowing marmot of North America digs tunnel systems with separate nesting chambers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Marmota_monax_UL_04.jpg?width=1024"},{"name":"Black-tailed Prairie Dog","rarity":"rare","id":"black-tailed-prairie-dog","subtitle":"Rodent","details":"This highly social ground squirrel lives in vast Great Plains towns and greets family members with a nose-to-nose kiss.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cynomys_ludovicianus_%2854906540630%29.jpg?width=1024"},{"name":"Alpine Marmot","rarity":"rare","id":"alpine-marmot","subtitle":"Rodent","details":"Living in family groups high in European alpine meadows, this stocky burrower hibernates up to eight months of the year.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/071_Wild_marmot_at_Grand_Muveran_Nature_Reserve_Photo_by_Giles_Laurent.jpg?width=1024"},{"name":"Eurasian Red Squirrel","rarity":"rare","id":"eurasian-red-squirrel","subtitle":"Rodent","details":"This tuft-eared tree squirrel of Eurasian forests buries thousands of seeds each autumn, planting forgotten trees as it goes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Squirrel_posing.jpg?width=1024"},{"name":"Eastern Gray Squirrel","rarity":"rare","id":"eastern-gray-squirrel","subtitle":"Rodent","details":"A nimble North American tree squirrel that can rotate its hind ankles 180 degrees to descend tree trunks head-first.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/EasternGraySquirrel_GAm.jpg?width=1024"},{"name":"Fox Squirrel","rarity":"rare","id":"fox-squirrel","subtitle":"Rodent","details":"The largest tree squirrel in North America, this rusty-orange species spends much of its day foraging on the ground for nuts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fox_Squirrel_%2814539535789%29.jpg?width=1024"},{"name":"Southern Flying Squirrel","rarity":"rare","id":"southern-flying-squirrel","subtitle":"Rodent","details":"This nocturnal glider steers between trees on a furred membrane, landing softly and scrambling upward to glide again.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Southern_Flying_Squirrel_-_Glaucomys_volans%2C_Arlington%2C_Virginia%2C_December_22%2C_2020_%2853406816432%29.jpg?width=800"},{"name":"Coypu","rarity":"rare","id":"coypu","subtitle":"Rodent","details":"A large semi-aquatic rodent from South America, the coypu swims with webbed hind feet and grazes on reeds along marshy banks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Myocastor_coypus_02.jpg?width=1024"},{"name":"Muskrat","rarity":"rare","id":"muskrat","subtitle":"Rodent","details":"This semi-aquatic North American rodent builds dome-shaped lodges of mud and reeds and can stay submerged for over 15 minutes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Muskrat_swimming_Ottawa.jpg?width=1024"},{"name":"Central American Agouti","rarity":"rare","id":"central-american-agouti","subtitle":"Rodent","details":"A sharp-eared rainforest rodent known for burying Brazil nuts and other large seeds, planting future trees as it forages.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Central_American_agouti_%28Dasyprocta_punctata%29_Paz_de_las_Aves.jpg?width=1024"},{"name":"Lowland Paca","rarity":"rare","id":"lowland-paca","subtitle":"Rodent","details":"A stout, spotted nocturnal rodent of Central and South American forests, the paca swims well and shelters in burrows near water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Paca_walking_in_grass_close_up_-_DPLA_-_826590946052c7217e313ec0a53c7f17.jpg?width=1024"},{"name":"Long-tailed Chinchilla","rarity":"rare","id":"long-tailed-chinchilla","subtitle":"Rodent","details":"High in the dry Andes, this dense-furred rodent grows dozens of hairs from each follicle, insulation for freezing nights.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chinchilla_lanigera_%28Wroclaw_zoo%29-2.JPG?width=1024"},{"name":"Eastern Grey Kangaroo","rarity":"rare","id":"eastern-grey-kangaroo","subtitle":"Marsupial","details":"Eastern grey kangaroos graze Australia's eastern forests and grasslands in mobs, and females can keep three joeys of different ages on the go at once.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Macropus_giganteus_-_Brunkerville.jpg?width=1024"},{"name":"Quokka","rarity":"rare","id":"quokka","subtitle":"Marsupial","details":"The quokka, a small wallaby from Rottnest Island off Western Australia, is famous for its cheerful face and fearless curiosity around visitors.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Setonix_brachyurus_on_Rottnest_Island_1.jpg?width=800"},{"name":"Common Wombat","rarity":"rare","id":"common-wombat","subtitle":"Marsupial","details":"This burrowing Tasmanian and Australian marsupial has cube-shaped droppings, which it stacks on rocks and logs to mark out its home territory.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vombatus_ursinus_-Maria_Island_National_Park.jpg?width=1024"},{"name":"Sugar Glider","rarity":"rare","id":"sugar-glider","subtitle":"Marsupial","details":"A sugar glider can sail over fifty metres through the Australian night, steering with the flap of skin stretched between its wrists and ankles.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Petaurus%20breviceps%20%28sugar%20glider%29.jpg?width=1024"},{"name":"Virginia Opossum","rarity":"rare","id":"virginia-opossum","subtitle":"Marsupial","details":"North America's only marsupial, the Virginia opossum famously plays dead when cornered — an involuntary faint that can last for hours.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Opossum_2.jpg?width=1024"},{"name":"Southern Tamandua","rarity":"rare","id":"southern-tamandua","subtitle":"Oddball","details":"This tree-climbing South American anteater tears into ant nests with hooked claws, then walks on its knuckles to keep those claws sharp.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/T_tetradactyla_1.jpg?width=1024"},{"name":"Brown-throated Sloth","rarity":"rare","id":"brown-throated-sloth","subtitle":"Oddball","details":"Moving so slowly that algae grows in its fur, the brown-throated sloth spends nearly its whole life hanging upside down in Central American trees.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bradypus.jpg?width=800"}]});
